CREATE OR REPLACE FUNCTION public.search_scientific_articles(query_text text, limit_count integer DEFAULT 5) RETURNS TABLE(id uuid,title text,authors text,abstract text,doi text,url text,year integer,keywords text[],rank real) LANGUAGE sql STABLE SET search_path=public AS $$ WITH q AS ( SELECT CASE WHEN lower(query_text) ~ '(cannabidiol|canabidiol|cbd)' AND lower(query_text) ~ '(anxiety|ansiedade|anxious)' THEN to_tsquery('english','(cannabidiol | cbd | canabidiol) & (anxiety | ansiedade | anxious)') ELSE plainto_tsquery('english',query_text) END AS en, plainto_tsquery('portuguese',query_text) AS pt ) SELECT a.id,a.title,a.authors,a.abstract,a.doi,a.url,a.year,a.keywords, greatest(ts_rank(to_tsvector('english',coalesce(a.title,'') || ' ' || coalesce(a.abstract,'') || ' ' || coalesce(array_to_string(a.keywords,' '),'')),q.en), ts_rank(to_tsvector('portuguese',coalesce(a.title,'') || ' ' || coalesce(a.abstract,'')),q.pt)) AS rank FROM public.scientific_articles a CROSS JOIN q WHERE to_tsvector('english',coalesce(a.title,'') || ' ' || coalesce(a.abstract,'') || ' ' || coalesce(array_to_string(a.keywords,' '),'')) @@ q.en OR to_tsvector('portuguese',coalesce(a.title,'') || ' ' || coalesce(a.abstract,'')) @@ q.pt ORDER BY rank DESC NULLS LAST,a.id LIMIT greatest(1,least(limit_count,10)); $$; GRANT EXECUTE ON FUNCTION public.search_scientific_articles(text,integer) TO authenticated,service_role;